package ma.autocarnet;
import java.util.*;import java.time.*;import org.json.*;
final class EngineCoach {
 static double median(List<Double> input){List<Double> a=new ArrayList<>(input);Collections.sort(a);int n=a.size();return n%2==1?a.get(n/2):(a.get(n/2-1)+a.get(n/2))/2;}
 static List<JSONObject> cycles(JSONObject data)throws Exception{List<JSONObject> result=new ArrayList<>();JSONObject anchor=null;double liters=0;for(JSONObject e:ReportPdf.entries(data)){if(!e.optString("type").equals("fuel"))continue;if(!e.optBoolean("hasKm",true)){anchor=null;liters=0;continue;}if(anchor==null){if(e.optBoolean("full"))anchor=e;continue;}if(e.isNull("liters")){anchor=e.optBoolean("full")?e:null;liters=0;continue;}liters+=e.getDouble("liters");if(e.optBoolean("full")&&e.getDouble("km")>anchor.getDouble("km")){double km=e.getDouble("km")-anchor.getDouble("km");JSONObject raw=e.optJSONObject("context"),context=new JSONObject();for(String k:new String[]{"mode","traffic","ac","shortTrips","load"})context.put(k,raw==null?"unknown":raw.optString(k,"unknown"));String key=context.getString("mode")+"|"+context.getString("traffic")+"|"+context.getString("ac")+"|"+context.getString("shortTrips")+"|"+context.getString("load");result.add(new JSONObject().put("id",e.getString("id")).put("from",anchor.getString("date")).put("to",e.getString("date")).put("km",km).put("fromKm",anchor.getDouble("km")).put("toKm",e.getDouble("km")).put("liters",liters).put("rate",100*liters/km).put("context",context).put("key",key).put("eligible",e.optBoolean("referenceEligible",true)));anchor=e;liters=0;}}return result;}
 static JSONObject reference(JSONObject data,JSONObject cycle,List<JSONObject> prior)throws Exception{
  JSONObject p=data.optJSONObject("coachProfile");if(p==null||!p.optBoolean("enabled")||!p.optString("vehicleName").equals(data.getJSONObject("vehicle").optString("name"))||cycle.getJSONObject("context").getString("mode").equals("unknown"))return null;
  JSONObject bounds=p.optJSONObject("bounds"),manual=bounds==null?null:bounds.optJSONObject(cycle.getJSONObject("context").getString("mode"));if(manual!=null)return new JSONObject().put("kind","manual").put("min",manual.getDouble("min")).put("max",manual.getDouble("max")).put("center",(manual.getDouble("min")+manual.getDouble("max"))/2).put("count",0).put("km",0);
  List<JSONObject> chosen=new ArrayList<>();double km=0;String since=p.optString("referenceSince","");for(JSONObject c:prior){if(!c.getString("key").equals(cycle.getString("key"))||c.getDouble("km")<100||!c.optBoolean("eligible")||(!since.isEmpty()&&c.getString("from").compareTo(since)<0))continue;chosen.add(c);km+=c.getDouble("km");if(chosen.size()>=3&&km>=500)break;}
  if(chosen.size()<3||km<500)return new JSONObject().put("kind","learning").put("count",chosen.size()).put("km",km);
  List<Double> rates=new ArrayList<>(),deviations=new ArrayList<>();for(JSONObject c:chosen)rates.add(c.getDouble("rate"));double center=median(rates);for(double rate:rates)deviations.add(Math.abs(rate-center));double tolerance=Math.max(.6,Math.max(center*.2,3*1.4826*median(deviations)));return new JSONObject().put("kind","learned").put("center",center).put("min",Math.max(.1,center-tolerance)).put("max",center+tolerance).put("count",chosen.size()).put("km",km);
 }
 static List<JSONObject> assessed(JSONObject data)throws Exception{List<JSONObject> all=cycles(data),result=new ArrayList<>();for(int i=0;i<all.size();i++){JSONObject c=all.get(i),ref=reference(data,c,all.subList(0,i));String status=c.getDouble("km")<100?"short":ref==null?"context":ref.getString("kind").equals("learning")?"learning":c.getDouble("rate")>ref.getDouble("max")+1e-9?"high":c.getDouble("rate")<ref.getDouble("min")-1e-9?"low":"usual";JSONObject previous=null;for(JSONObject r:result)if(r.getString("key").equals(c.getString("key")))previous=r;boolean high=status.equals("high"),repeated=high&&previous!=null&&previous.optBoolean("high");c.put("reference",ref==null?JSONObject.NULL:ref).put("high",high).put("repeated",repeated).put("status",repeated?"repeated":status);result.add(c);}return result;}
 static JSONObject month(JSONObject data,String month)throws Exception{YearMonth ym=YearMonth.parse(month);String start=ym.atDay(1).toString(),next=ym.plusMonths(1).atDay(1).toString();JSONArray selected=new JSONArray();double km=0,liters=0;int high=0;boolean repeated=false;for(JSONObject c:assessed(data)){if(c.getString("from").compareTo(start)<0||c.getString("to").compareTo(next)>0)continue;selected.put(c);km+=c.getDouble("km");liters+=c.getDouble("liters");if(c.optBoolean("high"))high++;if(c.optBoolean("repeated"))repeated=true;}boolean complete=selected.length()>0&&selected.getJSONObject(0).getString("from").equals(start)&&selected.getJSONObject(selected.length()-1).getString("to").equals(next);for(int j=1;j<selected.length();j++)if(!selected.getJSONObject(j).getString("from").equals(selected.getJSONObject(j-1).getString("to"))||selected.getJSONObject(j).getDouble("fromKm")!=selected.getJSONObject(j-1).getDouble("toKm"))complete=false;return new JSONObject().put("cycles",selected).put("km",km).put("liters",liters).put("rate",km>0?100*liters/km:JSONObject.NULL).put("complete",complete).put("highCount",high).put("repeated",repeated);}
 static String label(String status){switch(status){case "usual":return "Proche de votre repère";case "high":return "Au-dessus de votre repère";case "repeated":return "Hausse répétée à vérifier";case "low":return "Plus bas : relevés à confirmer";case "learning":return "Apprentissage en cours";case "short":return "Mesure trop courte";default:return "Profil / contexte à compléter";}}
 static String mode(String mode){switch(mode){case "city":return "Ville";case "highway":return "Autoroute";case "road":return "Route";case "mixed":return "Mixte";default:return "Non précisé";}}
 static void appendMonthly(ReportPdf.Layout pdf,JSONObject data,String month)throws Exception{
  JSONObject profile=data.optJSONObject("coachProfile");if(profile==null||!profile.optBoolean("enabled"))return;pdf.heading("Consommation : repères personnalisés");
  if(!profile.optString("vehicleName").equals(data.getJSONObject("vehicle").optString("name"))){pdf.paragraph("Profil à confirmer après changement de voiture. Aucune qualification de consommation.",3);return;}
  JSONObject result=month(data,month);if(result.isNull("rate")){pdf.paragraph("Pas de cycle mesurable entièrement sur cette période. Les achats du mois restent comptés ; aucun taux réel ni verdict n’est inventé.",3);return;}
  pdf.row("Consommation sur les cycles relevés",ReportPdf.num(result.getDouble("rate"))+" L/100 km");pdf.paragraph(ReportPdf.num(result.getDouble("liters"))+" L sur "+ReportPdf.num(result.getDouble("km"))+" km. "+(result.getBoolean("complete")?"Cycles entre relevés de plein aux limites du mois.":"Mesure partielle : elle ne représente pas forcément tout le mois."),3);
  JSONArray cycles=result.getJSONArray("cycles");for(int i=0;i<cycles.length();i++){JSONObject c=cycles.getJSONObject(i);pdf.ensure(60);pdf.paragraph(c.getString("from")+" au "+c.getString("to")+" · "+mode(c.getJSONObject("context").getString("mode"))+" · "+ReportPdf.num(c.getDouble("rate"))+" L/100 km : "+label(c.getString("status")),4);JSONObject ref=c.optJSONObject("reference");if(ref!=null&&!ref.getString("kind").equals("learning"))pdf.paragraph("Repère "+(ref.getString("kind").equals("learned")?"appris":"saisi")+" : "+ReportPdf.num(ref.getDouble("min"))+" à "+ReportPdf.num(ref.getDouble("max"))+" L/100 km.",2);}
  if(result.getInt("highCount")>0)pdf.paragraph("Vérifiez les litres et compteurs, puis les conditions de circulation, trajets courts, climatisation et charge. Contrôlez la pression préconisée et le suivi d’entretien. Si la hausse persiste dans des conditions comparables, demandez un diagnostic au garage. Aucune pièce en panne n’est identifiée par ce calcul.",6);
  pdf.paragraph("Repère appris : premiers cycles comparables, au moins 3 cycles et 500 km, médiane et marge robuste. Une proximité avec l’habitude ne prouve pas le bon état mécanique. Une donnée constructeur mixte d’homologation ne constitue pas une limite réelle en ville ou sur autoroute.",5);
 }
}
